import fs from 'node:fs';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import {createRequire} from 'node:module';
const {chromium}=createRequire(new URL('../web/package.json',import.meta.url))('playwright-core');
const dir='docs/research/photo-fill-20261107',out='.logs/photo-fill-20261107/final-browser',base=process.env.WANDER_BASE_URL||'http://127.0.0.1:8787';fs.mkdirSync(out,{recursive:true});
const read=f=>JSON.parse(fs.readFileSync(f,'utf8')),summary=read(dir+'/coverage.json'),expected=fs.readdirSync('backend/src/main/resources/catalog').filter(f=>f.endsWith('.json')).map(f=>read('backend/src/main/resources/catalog/'+f));
const catalog=[];for(const d of expected){const res=await fetch(base+'/api/catalog/destinations/'+d.id);assert.equal(res.status,200);const live=(await res.json()).destination;assert.equal(live.places.length,d.places.length);for(const p of d.places){const a=live.places.find(x=>x.id===p.id);assert(a);assert.equal(a.photos.length,p.photos.length,p.name);for(let i=0;i<p.photos.length;i++){const ph=p.photos[i],api=a.photos[i];assert.equal(api.caption,ph.caption||'');assert.equal(api.sourceUrl,ph.sourceUrl);assert.equal(api.author,ph.author);}}catalog.push(live);}
const venues=catalog.flatMap(d=>d.places.filter(p=>p.venue)),photoUrls=[...new Set(venues.flatMap(p=>p.photos.map(ph=>ph.url)))];assert.equal(venues.filter(p=>p.photos.length).length,summary.withPhotos);
let photoBytes=0;for(const url of photoUrls){const res=await fetch(new URL(url,base));assert.equal(res.status,200,url);assert.match(res.headers.get('content-type'),/^image\/jpeg/);const bytes=Buffer.from(await res.arrayBuffer());assert.equal(bytes[0],255);assert.equal(bytes[1],216);photoBytes+=bytes.length;if(url.startsWith('/catalog/photos/'))assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'),crypto.createHash('sha256').update(fs.readFileSync('backend/src/main/resources'+url)).digest('hex'));}
const picks=[['sa-pa','rs-sa-pa-hotel-de-la-coupole-sapa-f25e058c'],['ha-noi','rs-ha-noi-movenpick-hotel-hanoi-ce-9279c58b'],['ha-noi','rs-ha-noi-bun-cha-huong-lien-9a485287'],['ho-chi-minh','rs-ho-chi-minh-the-reverie-saigon-754f6908'],['nha-trang','venue-nha-trang-havana'],['ha-noi','rs-ha-noi-angelina-sofitel-legend-57e2dc95'],['ho-chi-minh','rs-ho-chi-minh-anan-saigon-cce45aff']];
const browser=await chromium.launch({channel:'chrome',headless:true}),results=[];
try{for(const width of[390,1440]){const context=await browser.newContext({viewport:{width,height:width===390?844:1000},locale:'vi-VN',reducedMotion:'reduce',isMobile:width===390,hasTouch:width===390}),page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));page.setDefaultTimeout(25000);await page.addInitScript(()=>localStorage.setItem('wander.web.onboarding.v1','{"done":true}'));
 try{for(const [dest,id]of picks){const p=catalog.find(d=>d.id===dest).places.find(p=>p.id===id);assert(p?.photos.length,p?.name);await page.goto(base+'/?intro=0#/dest/'+dest+'/'+p.category,{waitUntil:'domcontentloaded'});const row=page.locator('[data-place-id="'+id+'"]');await row.waitFor();await row.scrollIntoViewIfNeeded();await row.locator('img[data-image-ready="true"]').waitFor();if(p.photos[0].caption)assert.equal(await row.locator('.pr-photo-caption').innerText(),p.photos[0].caption);await row.locator('.pr-photo').click();const dialog=page.getByRole('dialog',{name:p.name,exact:true});await dialog.waitFor();await dialog.locator('.pd-photo img[data-image-ready="true"]').waitFor();if(p.photos[0].caption)assert.equal(await dialog.locator('.pd-photo-caption').first().innerText(),p.photos[0].caption);assert.deepEqual(await page.locator('#screen,[role="dialog"],.pr-photo-caption,.pd-photo-caption').evaluateAll(es=>es.filter(e=>e.clientWidth&&e.scrollWidth>e.clientWidth+1).map(e=>e.className)),[]);await page.screenshot({path:out+'/'+width+'-'+id+'.png'});await dialog.getByRole('button',{name:'Đóng',exact:true}).click();}assert.deepEqual(errors,[]);results.push({width,status:'PASS',venuesChecked:picks.length,errors});}
 catch(e){await page.screenshot({path:out+'/'+width+'-FAILED.png'});results.push({width,status:'FAIL',error:e.message,errors});}finally{await context.close();}console.log(JSON.stringify(results.at(-1)));}
}finally{await browser.close();}
const result={checkedAt:new Date().toISOString(),baseUrl:base,catalogPlaces:summary.catalogPlaces,venueCards:venues.length,venueCardsWithPhotos:summary.withPhotos,withDirectVenuePhotos:summary.withDirectVenuePhotos,withHotelContextOnly:summary.withHotelContextOnly,uniqueVenueImageUrlsVerified:photoUrls.length,photoBytesVerified:photoBytes,sourceAndCaptionParity:true,browser:results};fs.writeFileSync(dir+'/live-verification.json',JSON.stringify(result,null,2)+'\n');process.exitCode=results.every(r=>r.status==='PASS')?0:1;
